export function Schedule({
  title = "{{title}}",
  view = "{{view}}",
  accent = "{{accent}}",
  showLocation = {{showLocation}},
  density = {{density}},
}) {
  const items = [
    { time: "09:00", iso: "2026-08-18T09:00", event: "Team standup", location: "Studio A" },
    { time: "11:30", iso: "2026-08-18T11:30", event: "Design review", location: "Meeting Room 2" },
    { time: "13:00", iso: "2026-08-18T13:00", event: "Lunch break", location: "Break room" },
    { time: "15:30", iso: "2026-08-18T15:30", event: "Client call", location: "Video call" },
  ];
  const week = view === "week";
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 16, lineHeight: 1.5, color: "#241430",
      background: "#FAF7F2", borderRadius: 12, padding: "18px 20px", boxSizing: "border-box", width: 320 }}>
      <h3 style={{ margin: "0 0 12px", fontSize: 15, fontWeight: 700 }}>{title}</h3>
      <ol style={{ listStyle: "none", margin: 0, padding: 0, display: "flex",
        flexDirection: week ? "row" : "column", flexWrap: week ? "wrap" : "nowrap", gap: week ? 10 : 0 }}>
        {items.map((item) => (
          <li key={item.time} style={{ display: "flex", flexDirection: week ? "column" : "row",
            gap: week ? 4 : 12, borderLeft: week ? "none" : `3px solid ${accent}`,
            borderTop: week ? `3px solid ${accent}` : "none",
            padding: week ? "8px 10px 0" : `${density}px 0 ${density}px 12px`,
            flex: week ? "1 1 130px" : "initial" }}>
            <time dateTime={item.iso} style={{ fontWeight: 700, fontVariantNumeric: "tabular-nums",
              width: week ? "auto" : 52, flexShrink: 0, color: accent }}>{item.time}</time>
            <div>
              <p style={{ margin: 0, fontWeight: 600, fontSize: 14 }}>{item.event}</p>
              {showLocation && <p style={{ margin: "2px 0 0", fontSize: 12, color: "#241430aa" }}>{item.location}</p>}
            </div>
          </li>
        ))}
      </ol>
    </div>
  );
}
